 "content": "def transform(grid):
    """Extrapolate the repeating parallel color bands encoded by the marks."""
    h, w = len(grid), len(grid[0])

    # Full-width horizontal stripes encode a repeating sequence by row index.
    stripes = {}
    for r, row in enumerate(grid):
        vals = set(row)
        if len(vals) == 1 and 0 not in vals:
            stripes[r] = row[0]
    if stripes:
        period = len(stripes)
        by_residue = {r % period: color for r, color in stripes.items()}
        return [[by_residue[r % period] for _ in range(w)] for r in range(h)]

    # Otherwise the marks are parallel down-right diagonals. Their offsets
    # c-r are the bands of one repeating diagonal pattern.
    offsets = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color != 0:
                d = c - r
                if d in offsets and offsets[d] != color:
                    raise ValueError("inconsistent color along a diagonal band")
                offsets[d] = color
    period = len(offsets)
    by_residue = {d % period: color for d, color in offsets.items()}
    return [[by_residue[(c - r) % period] for c in range(w)] for r in range(h)]
